<template>
  <AppFrame active="issues">
    <view class="xr-content review-page"><view v-if="issue && allowed" class="review-wrap"><view class="review-heading"><view><view class="xr-page-title">复核闭环</view><view class="xr-page-copy">确认整改佐证是否满足闭环要求。</view></view><view class="xr-status xr-status-review">待复核</view></view><view class="review-grid"><view class="xr-card original-card"><view class="xr-section-title">原始隐患</view><view class="original-copy">{{ issue.description }}</view><view class="review-facts"><view><text>上报人员</text><strong>{{ issue.reporter }}</strong></view><view><text>上报时间</text><strong>{{ issue.createdAt }}</strong></view><view><text>现场位置</text><strong>{{ issue.location || '未标注' }}</strong></view><view><text>责任部门</text><strong>{{ issue.assigneeDept }}</strong></view></view><view class="review-photo"><image v-if="issue.attachments&&issue.attachments.length" :src="issue.attachments[0]" mode="aspectFill"/><view v-else>等待原始现场图片</view></view></view><view class="xr-card remediation-card"><view class="evidence-header"><view><view class="xr-section-title">整改佐证</view><view class="xr-caption">市场营销部提交的材料</view></view><view class="xr-status xr-status-review">待复核</view></view><view class="remediation-copy">{{ issue.rectification ? issue.rectification.note : '尚未提交整改材料。' }}</view><view class="remediation-meta">提交时间 {{ issue.rectification ? issue.rectification.submittedAt : '-' }}</view><view class="review-photos"><view v-for="file in evidenceFiles" :key="file" class="review-thumb"><image :src="file" mode="aspectFill"/></view><view v-if="!evidenceFiles.length" class="review-thumb empty-thumb">无图片</view></view><view class="field"><text class="xr-field-label">闭环意见</text><textarea v-model="reviewNote" class="xr-textarea" placeholder="填写复核意见，退回整改时请明确原因"/></view><view class="review-buttons"><button class="xr-btn xr-btn-danger" @click="returnIssue">退回整改</button><button class="xr-btn xr-btn-primary" @click="close">确认闭环</button></view></view></view></view><view v-else-if="issue" class="xr-empty">无复核权限，已返回可访问范围。</view><view v-else class="xr-empty">未找到待复核隐患</view></view>
  </AppFrame>
</template>
<script setup>
import { computed, ref } from 'vue'
import { onLoad } from '@dcloudio/uni-app'
import AppFrame from '../../components/AppFrame.vue'
import { demoStore } from '../../stores/demo'
let id = ''
const issue = computed(() => demoStore.issues.find((item) => item.id === id))
const allowed = computed(() => demoStore.can('issue-review', issue.value))
const reviewNote = ref('')
const evidenceFiles = computed(() => issue.value?.rectification?.attachments || [])
onLoad((options) => { id = options.id })
function back() { uni.navigateBack({ delta: 1, fail: () => uni.switchTab({ url: '/pages/index/index' }) }) }
function returnIssue() { if (!allowed.value || !reviewNote.value) { uni.showToast({ title: '请填写退回原因', icon: 'none' }); return }; demoStore.returnIssue(id, reviewNote.value); uni.showToast({ title: '已退回整改', icon: 'success' }); setTimeout(back, 450) }
function close() { if (!allowed.value) return; demoStore.closeIssue(id, reviewNote.value || undefined); uni.showToast({ title: '已确认闭环', icon: 'success' }); setTimeout(back, 450) }
</script>
