font-size:11px}.remediation-meta{margin-top:6px;font-size:10px}.review-photos{gap:7px;margin-top:11px}.review-thumb{width:62px;height:62px}.empty-thumb{font-size:9px}.review-buttons{gap:8px;margin-top:16px}}
